  async function toggleShopping(id,checked){const item=state.shopping.find(x=>x.id===id);if(!item)return;const next={...item,checked};try{await storePut(STORE_SHOPPING,next);state.shopping=state.shopping.map(x=>x.id===id?next:x);render();}catch{notify('Could not update item');}}
